function signalState(s){return s.id==='gps'&&state.gpsLost?'Unavailable':s.id==='battery'&&state.batteryStale?'Stale':s.status;}
function sourceCounts(){return {current:suite.sensors.filter(s=>signalState(s)==='Current').length+(state.apTimeout?0:1),total:suite.sensors.length+2};}
function healthPanel(){const count=sourceCounts();return `<div class="pill-row">${tag('MOCK SENSOR NETWORK','neutral')}${tag(count.current+' / '+count.total+' current',count.current<count.total-1?'warning':'')}</div>${suite.sensors.map(s=>{const status=signalState(s);return `<details class="sensor-details"><summary><span class="sensor-dot ${status==='Current'?'':'unavailable'}" style="display:inline-block;margin-right:8px"></span>${esc(s.signal)}<span style="float:right;font-size:10px;color:var(--secondary)">${status} · ${status==='Current'?esc(s.age):status==='Stale'?'42 s':'—'}</span></summary>${row('Selected source',esc(s.name))}${row('Transport',s.transport)}${row('Message / PGN',esc(s.pgn))}${row('Cadence',esc(s.rate))}${row('Source precedence',s.priority)}<button class="btn full" data-sensor-id="${s.id}">Configure this sensor</button></details>`;}).join('')}<details class="sensor-details"><summary>Autopilot adapter<span style="float:right;font-size:10px;color:var(--secondary)">${state.apTimeout?'Aging':'Current'} · 0.6 s</span></summary>${row('Selected source','Generic heading adapter')}${row('Control',state.apEnabled?'Preview enabled':'Read-only')}${button('Adapter configuration','showAdapter','full')}</details><details class="sensor-details"><summary>Water tank<span style="float:right;font-size:10px;color:var(--secondary)">No source</span></summary>${row('Signal state','Unavailable')}${button('Assign a sensor','addSensor','full')}</details><div class="section-label">Explore data-loss states</div>${toggle('GPS signal lost','gpsLoss',state.gpsLost,'Persistent alert and forecast unavailable state')}${toggle('Battery data stale','batteryStale',state.batteryStale,'Remove stale arrival predictions')}${suiteLink('Manage all sensors','Add, calibrate, prioritise or reconnect','showSensors','gauge')}${button(icon('download')+' Export diagnostics','exportDiagnostics','full')}${note('Freshness applies to each signal. A message on the bus does not make every measurement current.')}`;}
